; stack.asm -- chapter 12: three pairs pushed and popped
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "stack.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; Three pairs pushed and popped again. The stack starts at SYS_AREA and
; grows down; POP gives the pairs back last first.
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
        ld bc, $1234
        ld de, $5678
        ld hl, $9ABC
p0:     push bc
p1:     push de
p2:     push hl
full:   pop bc                  ; the last in comes out first
        pop de
        pop hl
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
